/*
 * The one typed entry point for content (server side). Pages and server
 * components import it via src/lib/content.ts. Every export is typed by
 * content/schema.ts; the build-time count checks live in src/lib/content.ts.
 *
 *   site.ts        site chrome              (slim: client components load it, D7)
 *   hand.ts        the hand + Coffee card   (slim: client components load it, D7)
 *   images.ts      image registry           (generated by scripts/images/fetch-and-build.mjs)
 *   cases/*.ts     the three case studies   (server only)
 *   pages/*.ts     every other page's text  (server only)
 */
import { frontDoor } from './cases/front-door'
import { sharedFoundations } from './cases/shared-foundations'
import { teamOfTeams } from './cases/team-of-teams'
import { coffeeEgg, hand } from './hand'
import { about } from './pages/about'
import { contact } from './pages/contact'
import { home } from './pages/home'
import { management } from './pages/management'
import { moreProjects } from './pages/more-projects'
import { notFound } from './pages/not-found'
import { workshopMethods } from './pages/workshop-methods'
import type { Content } from './schema'
import { site } from './site'

export const content = {
  site,
  hand,
  home,
  caseStudies: [teamOfTeams, sharedFoundations, frontDoor],
  management,
  moreProjects,
  about,
  contact,
  notFound,
  coffeeEgg,
  workshopMethods,
} satisfies Content

export const { caseStudies } = content

export { about, coffeeEgg, contact, hand, home, management, moreProjects, notFound, site, workshopMethods }
export { images } from './images'
